def squash(s: str) -> str:
    if not s:
        return ""
    out: list[str] = []
    n = len(s)
    i = 0
    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1
        run = j - i
        escaped = "\\" + c if ("0" <= c <= "9" or c == "\\") else c
        if run >= 3:
            out.append(f"{run}{escaped}")
        elif run == 2:
            out.append(escaped * 2)
        else:
            out.append(escaped)
        i = j
    return "".join(out)
